// Payload contract (see backend/app/execution/adapters/n8n_email.py):
// POST body = { request_id, plan_id, action_id, action: { tool, operation, parameters: { to, subject, body } } }.
// The Webhook node always nests the actual POST body under `.body`
// (alongside headers/params/query) - unwrap it here rather than treating
// the whole wrapper as the payload.
const body = $input.item.json.body;
const action = body.action || {};
const params = action.parameters || {};

if (action.tool !== 'email' || action.operation !== 'send_email') {
  throw new Error(`Unsupported action for this workflow: expected email.send_email, got ${action.tool}.${action.operation}`);
}

// `to` must already be a non-empty array of real, deterministically-
// resolved addresses (app/services/contact_resolution_service.py) - this
// workflow does not look up or trust any other recipient information.
const to = Array.isArray(params.to)
  ? params.to.filter((addr) => typeof addr === 'string' && addr.includes('@'))
  : [];
if (to.length === 0) {
  throw new Error('Missing required parameter: to (must be a non-empty array of resolved email addresses)');
}
if (!params.subject || !params.body) {
  throw new Error('Missing required parameters: subject and body are required');
}

return {
  json: {
    request_id: body.request_id,
    plan_id: body.plan_id,
    action_id: body.action_id,
    to: to.join(','),
    subject: params.subject,
    text: params.body,
  },
};
